<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->query("SELECT e.*,b.name branch FROM exams e LEFT JOIN branches b ON b.id=e.branch_id WHERE e.exam_date>=CURDATE() ORDER BY e.exam_date,e.start_time");page_top('Exam Center');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Exam</th><th>Type</th><th>Date</th><th>Time</th><th>Room</th><th>Status</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><?=e($r['exam_date'])?></td><td><?=e($r['start_time'])?>–<?=e($r['end_time'])?></td><td><?=e($r['room'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>